class Student:
    def __init__(self, name, score):
        self.name = name        # this object's own data
        self.score = score
    def passed(self):
        return self.score >= 60

a = Student("ani", 85)     # one object
b = Student("bala", 40)    # another, own data
print(a.passed(), b.passed())   # True False

